import docx
from docx.shared import Pt, Inches
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
import os

def create_unique_master_pdkp(out_path=r"d:\Антигравити\legal_estate\deals\ПДКП_Протасовы_Фирсова.docx"):
    doc = docx.Document()

    # Точные поля корпоративного стандарта «Этажи» (из образца Шатовой/Балакиной):
    # Left: 20 mm, Right: 15 mm, Top: 18 mm, Bottom: 18 mm
    for s in doc.sections:
        s.top_margin = Inches(0.71)    # 18 mm
        s.bottom_margin = Inches(0.71) # 18 mm
        s.left_margin = Inches(0.79)   # 20 mm
        s.right_margin = Inches(0.59)  # 15 mm
        s.page_width = Inches(8.27)    # 210 mm
        s.page_height = Inches(11.69)  # 297 mm

    # Точная ширина полосы набора текста в dxa: (8.27 - 0.79 - 0.59) * 1440 = 9921 dxa
    BODY_DXA = 9921
    INDENT = Pt(27.0)  # Единая красная строка 1.0 см (27 pt) по эталону «Этажи»

    def set_p_format(p, font_size=11.0, space_before=0, space_after=1.5, line_spacing=1.10, align=WD_ALIGN_PARAGRAPH.JUSTIFY, first_indent=INDENT):
        p.paragraph_format.space_before = Pt(space_before)
        p.paragraph_format.space_after = Pt(space_after)
        p.paragraph_format.line_spacing = line_spacing
        p.paragraph_format.left_indent = Pt(0)
        p.paragraph_format.right_indent = Pt(0)
        p.alignment = align
        if first_indent is not None:
            p.paragraph_format.first_line_indent = first_indent
        else:
            p.paragraph_format.first_line_indent = Pt(0)

    def add_h(doc, text):
        p = doc.add_paragraph()
        set_p_format(p, font_size=11.0, space_before=3.5, space_after=1.5, line_spacing=1.10, align=WD_ALIGN_PARAGRAPH.CENTER, first_indent=None)
        p.paragraph_format.keep_with_next = True
        r = p.add_run(text)
        r.bold = True
        r.font.name = "Times New Roman"
        r.font.size = Pt(11.0)
        return p

    def add_p(doc, text, bold_prefix="", space_after=1.5, space_before=0):
        p = doc.add_paragraph()
        set_p_format(p, font_size=11.0, space_before=space_before, space_after=space_after, line_spacing=1.10, align=WD_ALIGN_PARAGRAPH.JUSTIFY, first_indent=INDENT)
        if bold_prefix:
            r_pre = p.add_run(bold_prefix)
            r_pre.bold = True
            r_pre.font.name = "Times New Roman"
            r_pre.font.size = Pt(11.0)
        r = p.add_run(text)
        r.font.name = "Times New Roman"
        r.font.size = Pt(11.0)
        return p

    def add_city_date(doc, city_text="г. Пенза", date_text="«___» ____________ 202_ года"):
        p = doc.add_paragraph()
        set_p_format(p, font_size=11.0, space_before=0, space_after=3.0, line_spacing=1.10, align=WD_ALIGN_PARAGRAPH.LEFT, first_indent=None)
        pPr = p._element.get_or_add_pPr()
        tabs = OxmlElement('w:tabs')
        tab = OxmlElement('w:tab')
        tab.set(qn('w:val'), 'right')
        tab.set(qn('w:pos'), str(BODY_DXA))
        tabs.append(tab)
        pPr.append(tabs)

        r_city = p.add_run(city_text)
        r_city.bold = True
        r_city.font.name = "Times New Roman"
        r_city.font.size = Pt(11.0)
        p.add_run("\t")
        r_date = p.add_run(date_text)
        r_date.bold = True
        r_date.font.name = "Times New Roman"
        r_date.font.size = Pt(11.0)
        return p

    def add_sig_block(doc, title, printed_name, space_after=3.5, is_last=False):
        p_t = doc.add_paragraph()
        set_p_format(p_t, font_size=11.0, space_before=3.0, space_after=1.0, line_spacing=1.10, align=WD_ALIGN_PARAGRAPH.LEFT, first_indent=None)
        p_t.paragraph_format.keep_with_next = True
        r = p_t.add_run(title)
        r.bold = True
        r.font.name = "Times New Roman"
        r.font.size = Pt(11.0)

        # Строка для подписи
        p_line = doc.add_paragraph()
        set_p_format(p_line, font_size=2.0, space_before=0, space_after=1.0, line_spacing=1.10, align=WD_ALIGN_PARAGRAPH.LEFT, first_indent=None)
        p_line.paragraph_format.keep_with_next = True
        pPr = p_line._element.get_or_add_pPr()
        pBdr = OxmlElement('w:pBdr')
        bottom = OxmlElement('w:bottom')
        bottom.set(qn('w:val'), 'single')
        bottom.set(qn('w:sz'), '6')
        bottom.set(qn('w:space'), '1')
        bottom.set(qn('w:color'), '000000')
        pBdr.append(bottom)
        pPr.append(pBdr)

        # Подстрочник: ФИО полностью (слева) и подпись (справа по правому краю)
        p_sub = doc.add_paragraph()
        set_p_format(p_sub, font_size=8.5, space_before=0, space_after=1.0, line_spacing=1.10, align=WD_ALIGN_PARAGRAPH.LEFT, first_indent=None)
        p_sub.paragraph_format.keep_with_next = True
        pPr3 = p_sub._element.get_or_add_pPr()
        tabs = OxmlElement('w:tabs')
        tab = OxmlElement('w:tab')
        tab.set(qn('w:val'), 'right')
        tab.set(qn('w:pos'), str(BODY_DXA))
        tabs.append(tab)
        pPr3.append(tabs)

        r_sub1 = p_sub.add_run("ФИО полностью")
        r_sub1.font.name = "Times New Roman"
        r_sub1.font.size = Pt(8.5)
        r_sub1.font.italic = True
        p_sub.add_run("\t")
        r_sub2 = p_sub.add_run("подпись")
        r_sub2.font.name = "Times New Roman"
        r_sub2.font.size = Pt(8.5)
        r_sub2.font.italic = True

        # Печатное имя стороны
        p_name = doc.add_paragraph()
        set_p_format(p_name, font_size=10.5, space_before=0, space_after=space_after, line_spacing=1.10, align=WD_ALIGN_PARAGRAPH.LEFT, first_indent=None)
        if not is_last:
            p_name.paragraph_format.keep_with_next = True
        rn = p_name.add_run(printed_name)
        rn.font.name = "Times New Roman"
        rn.font.size = Pt(10.5)

    # =========================================================================
    # ШАПКА И ПРЕАМБУЛА
    # =========================================================================
    p_title = doc.add_paragraph()
    set_p_format(p_title, font_size=12.0, space_before=0, space_after=2.0, align=WD_ALIGN_PARAGRAPH.CENTER, first_indent=None)
    r_t = p_title.add_run("ПРЕДВАРИТЕЛЬНЫЙ ДОГОВОР КУПЛИ-ПРОДАЖИ КВАРТИРЫ")
    r_t.bold = True
    r_t.font.name = "Times New Roman"
    r_t.font.size = Pt(12.0)

    add_city_date(doc, "г. Пенза", "«___» ____________ 202_ года")

    p_pre1 = doc.add_paragraph()
    set_p_format(p_pre1, font_size=11.0, space_before=0, space_after=2.0, line_spacing=1.12, first_indent=INDENT)
    p_pre1.add_run("Мы, нижеподписавшиеся: гражданин РФ ").font.name = "Times New Roman"
    r = p_pre1.add_run("Протасов Олег Иванович")
    r.bold = True
    r.font.name = "Times New Roman"
    p_pre1.add_run(", 15.04.1988 года рождения, пол: мужской, место рождения: гор. Пенза, паспорт гражданина РФ: серия 5612 № 345678, выдан Отделом УФМС России по Пензенской области в Ленинском р-не г. Пензы 20.04.2012 г., код подразделения: 580-001, адрес регистрации: Пензенская область, г. Пенза, ул. Суворова, д. 145, кв. 12, и гражданин РФ ").font.name = "Times New Roman"
    r = p_pre1.add_run("Протасов Виктор Иванович")
    r.bold = True
    r.font.name = "Times New Roman"
    p_pre1.add_run(", 22.09.1963 года рождения, пол: мужской, место рождения: гор. Пенза, паспорт гражданина РФ: серия 5608 № 901234, выдан Отделом внутренних дел Октябрьского р-на г. Пензы 05.10.2008 г., код подразделения: 580-002, адрес регистрации: Пензенская область, г. Пенза, ул. Тернопольская, д. 7, кв. 34, именуемые в дальнейшем совместно ").font.name = "Times New Roman"
    r = p_pre1.add_run("«Продавцы»")
    r.bold = True
    r.font.name = "Times New Roman"
    p_pre1.add_run(", с одной стороны, и").font.name = "Times New Roman"

    p_pre2 = doc.add_paragraph()
    set_p_format(p_pre2, font_size=11.0, space_before=0, space_after=2.0, line_spacing=1.12, first_indent=INDENT)
    p_pre2.add_run("гражданка РФ ").font.name = "Times New Roman"
    r = p_pre2.add_run("Фирсова Ангелина Сергеевна")
    r.bold = True
    r.font.name = "Times New Roman"
    p_pre2.add_run(", 10.08.1995 года рождения, пол: женский, место рождения: гор. Пенза, паспорт гражданина РФ: серия 5615 № 123456, выдан Отделом УФМС России по Пензенской области в Первомайском р-не г. Пензы 15.08.2015 г., код подразделения: 580-003, адрес регистрации: Пензенская область, г. Пенза, ул. Мира, д. 40, кв. 89, именуемая в дальнейшем ").font.name = "Times New Roman"
    r = p_pre2.add_run("«Покупатель»")
    r.bold = True
    r.font.name = "Times New Roman"
    p_pre2.add_run(", с другой стороны, при совместном упоминании именуемые «Стороны», а по отдельности — «Сторона», находясь в здравом уме и ясной памяти, действуя добровольно, заключили настоящий Предварительный договор (далее — «Договор») о нижеследующем:").font.name = "Times New Roman"

    # =========================================================================
    # 1. ПРЕДМЕТ ПРЕДВАРИТЕЛЬНОГО ДОГОВОРА
    # =========================================================================
    add_h(doc, "1. Предмет предварительного договора")
    add_p(doc, "Стороны обязуются заключить в будущем Основной договор купли-продажи квартиры (далее — «Основной договор») на согласованных в настоящем Договоре условиях в срок не позднее «___» ____________ 202_ года включительно.", "1.1. ")
    add_p(doc, "По Основному договору Продавцы обязуются передать в собственность Покупателя, а Покупатель обязуется принять и оплатить объект недвижимого имущества — 1-комнатную квартиру, расположенную на 4 этаже жилого дома по адресу: Пензенская область, г. Пенза, ул. Тернопольская, д. 7, кв. 34, кадастровый номер: 58:29:1005008:1234, общей площадью 38,5 (тридцать восемь целых пять десятых) кв. м, жилой площадью 19,2 кв. м (далее — «Объект»).", "1.2. ")
    add_p(doc, "Указанный Объект принадлежит Продавцам на праве общей долевой собственности на основании следующих правоустанавливающих документов: Протасову Олегу Ивановичу принадлежит 1/3 (одна третья) доля в праве на основании Свидетельства о праве на наследство по закону от 14.11.2024 года, выданного нотариусом г. Пензы Ивановой М.А., реестровый номер: 58/12-н/58-2024-4-567, о чем в Едином государственном реестре недвижимости сделана запись регистрации № 58:29:1005008:1234-58/001/2024-3 от 22.11.2024 года; Протасову Виктору Ивановичу принадлежит 2/3 (две третьих) доли в праве, в том числе: 1/3 доля на основании Договора на передачу квартир в собственность граждан № 4512 от 12.03.1998 г., о чем в Едином государственном реестре недвижимости сделана запись регистрации № 58-58-35/002/2013-112 от 14.04.1998 г., и 1/3 доля на основании Свидетельства о праве на наследство по закону от 14.11.2024 года, выданного нотариусом г. Пензы Ивановой М.А., реестровый номер: 58/12-н/58-2024-4-568, о чем в Едином государственном реестре недвижимости сделана запись регистрации № 58:29:1005008:1234-58/001/2024-4 от 22.11.2024 года.", "1.3. ")
    add_p(doc, "По данным выписки из Единого государственного реестра недвижимости в отношении 1/3 доли Продавца Протасова Олега Ивановича зарегистрирован запрет на совершение регистрационных действий, запись регистрации № 58:29:1005008:1234-58/001/2026-1 от 15.02.2026 года, установленный в пользу Первомайского РОСП г. Пензы УФССП по Пензенской области на основании постановления судебного пристава-исполнителя от 15.02.2026 г. по исполнительному производству № 45892/26/58045-ИП. Иных ограничений прав, обременений, залогов кредитных организаций, ипотек и арестов в отношении Объекта не зарегистрировано. Продавец Протасов Олег Иванович обязуется своими силами и за счет собственных средств в срок не позднее чем за 5 (пять) рабочих дней до согласованной даты заключения Основного договора полностью погасить задолженность по исполнительному производству и обеспечить внесение в ЕГРН записи о прекращении (снятии) указанного запрета, что подтверждается свежей выпиской из ЕГРН с усиленной квалифицированной электронной подписью органа регистрации прав. Неисполнение данного обязательства признается виновным отказом Продавцов от сделки с последствиями по п. 4.2 настоящего Договора.", "1.4. ")
    add_p(doc, "Объект передается Покупателю в пригодном для постоянного проживания санитарном качественном состоянии, полностью свободным от мебели, бытовой техники и любых личных вещей Продавцов.", "1.5. ")

    # =========================================================================
    # 2. ЦЕНА ОБЪЕКТА И ПОРЯДОК РАСЧЕТОВ
    # =========================================================================
    add_h(doc, "2. Цена Объекта и порядок расчетов")
    add_p(doc, "Стороны оценивают Объект и продают его по соглашению Сторон за 7 000 000 (Семь миллионов) рублей 00 копеек. Соглашение о цене является существенным условием настоящего Договора. Указанная цена является фиксированной и пересмотру не подлежит.", "2.1. ")
    add_p(doc, "Оплата стоимости Объекта производится Покупателем в следующем согласованном порядке:", "2.2. ")
    add_p(doc, "— Сумма в размере 100 000 (Сто тысяч) рублей 00 копеек выплачивается Покупателем за счет собственных денежных средств в день подписания настоящего Договора в качестве единого ЗАДАТКА наличными денежными средствами Продавцу Протасову Виктору Ивановичу, который принимает указанные денежные средства от своего имени, а также с прямого согласия и по поручению второго Продавца Протасова Олега Ивановича. Продавцы подтверждают, что получение суммы задатка Протасовым В.И. признается надлежащим исполнением обязательства Покупателя перед ОБЕИМИ Продавцами в полном объеме (ст. 312 ГК РФ), порождает солидарную ответственность Продавцов по настоящему Договору и возврату задатка по ст. 322, 381 ГК РФ, и в полном объеме засчитывается в счет общей стоимости Объекта. Взаиморасчеты между Продавцами производятся ими самостоятельно. Факт передачи задатка подтверждается совместной письменной распиской Сторон (Приложение № 1 к настоящему Договору);", "")
    add_p(doc, "— Сумма в размере 5 000 000 (Пять миллионов) рублей 00 копеек оплачивается за счет собственных денежных средств Покупателя в день подписания Основного договора с использованием Сервиса безопасных расчетов (СБР) либо безотзывного покрытого аккредитива Банка с выплатой Продавцам после государственной регистрации перехода права собственности к Покупателю в следующем распределении: Протасову Олегу Ивановичу — 2 300 000 (Два миллиона триста тысяч) рублей 00 копеек; Протасову Виктору Ивановичу — 2 700 000 (Два миллиона семьсот тысяч) рублей 00 копеек. Расходы по СБР / аккредитиву несет Покупатель. По соглашению Сторон расчет собственными средствами (или их частью) может производиться наличными деньгами непосредственно в день подписания Основного договора по письменным распискам Продавцов без использования банковских сервисов;", "")
    add_p(doc, "— Сумма в размере 1 000 000 (Один миллион) рублей 00 копеек оплачивается за счет целевых кредитных средств, предоставляемых Покупателю Банком-кредитором по кредитному договору, с перечислением на банковский счет Продавца Протасова Виктора Ивановича после государственной регистрации перехода права собственности на Объект к Покупателю и государственной регистрации ипотеки в силу закона в пользу Банка-кредитора;", "")
    add_p(doc, "— Сумма в размере 900 000 (Девятьсот тысяч) рублей 00 копеек оплачивается за счет средств Материнского (семейного) капитала (Федеральный закон от 29.12.2006 № 256-ФЗ) путем безналичного перечисления Отделением Фонда пенсионного и социального страхования РФ (СФР) непосредственно на расчетный счет Продавца Протасова Виктора Ивановича в счет причитающейся ему части стоимости Объекта (для формирования единого заявления в СФР без дробления платежей между получателями), в срок не позднее 21 (двадцати одного) рабочего дня со дня принятия положительного решения СФР по заявлению Покупателя.", "")
    add_p(doc, "В соответствии с пунктом 5 статьи 488 Гражданского кодекса РФ право залога (ипотеки в силу закона) у Продавцов на Объект в связи с расчетами после государственной регистрации перехода права собственности (в том числе с использованием Сервиса безопасных расчетов / аккредитива, кредитных средств Банка и средств материнского капитала) НЕ ВОЗНИКАЕТ.", "2.3. ")
    add_p(doc, "В соответствии со статьями 430, 313 и 382 Гражданского кодекса РФ Стороны согласовали, что Покупатель вправе определить в качестве приобретателя Объекта (Покупателя по Основному договору) как себя лично, так и указанное им третье лицо (в том числе несовершеннолетних детей во исполнение требований законодательства РФ о материнском капитале, супруга либо соинвестора) без необходимости получения дополнительного согласия Продавцов и без изменения согласованной цены Объекта. Сумма задатка, внесенная Покупателем, признается надлежащим обеспечением обязательств по заключению Основного договора с номинированным третьим лицом и подлежит безусловному зачету в счет оплаты покупной цены Объекта по Основному договору, а у Покупателя не возникает права требовать возврата задатка как неосновательного обогащения (ст. 1102 ГК РФ). При виновном неисполнении обязательств Продавцами возврат задатка производится лицу, фактически внесшему денежные средства (Покупателю по настоящему Договору).", "2.4. ")

    # =========================================================================
    # 3. СРОКИ И ПОРЯДОК ПЕРЕДАЧИ ОБЪЕКТА И ЗАРЕГИСТРИРОВАННЫЕ ЛИЦА
